<script setup>
import {Head,Link} from '@inertiajs/vue3';defineProps({tab:String,deliveries:Array,routeCustomers:Object,stats:Object,collections:Object})
const tabs=[['deliveries','Deliveries','bi-box-seam'],['route','Route','bi-signpost-2'],['collections','Collections','bi-wallet2'],['profile','Profile','bi-person']]
</script>
<template><Head title="Delivery route"/><main class="portal-app delivery-app"><header class="portal-head"><div class="portal-brand"><span class="portal-mark">DN</span><div><strong>DairyNex Delivery</strong><small>{{new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'short'})}}</small></div></div><Link href="/logout" method="post" as="button" class="portal-logout">Sign out</Link></header><div class="portal-content">
<template v-if="tab==='deliveries'"><p class="portal-eyebrow">TODAY'S ROUTE</p><h1>Hi, {{ $page.props.auth.user.name }}</h1><div class="portal-stats compact"><article><small>Assigned</small><strong>{{stats.assigned}}</strong></article><article><small>Done</small><strong>{{stats.completed}}</strong></article><article><small>Pending</small><strong>{{stats.pending}}</strong></article><article><small>Skipped</small><strong>{{stats.skipped}}</strong></article></div><div v-for="(d,index) in deliveries" :key="d.id" class="portal-card delivery-card"><div class="delivery-card-head"><span class="delivery-index">{{index+1}}</span><div><strong>{{d.customer}}</strong><small>{{d.route}} · {{d.slot}}</small></div><span class="portal-badge" :class="{'done':d.status_id===3,'skipped':d.status_id===4}">{{d.status}}</span></div><p>{{d.address||'Address not provided'}}<br/><a v-if="d.mobile" :href="`tel:${d.mobile}`">{{d.mobile}}</a></p><div class="delivery-products"><span v-for="item in d.products" :key="item">{{item}}</span></div><div class="portal-section-head"><small>Due value ₹{{d.amount}}</small><Link :href="`/deliveries/${d.id}`" class="portal-action">Open delivery</Link></div></div><p v-if="!deliveries.length" class="portal-card portal-muted">No deliveries assigned for today.</p></template>
<template v-else-if="tab==='route'"><p class="portal-eyebrow">YOUR DELIVERY ORDER</p><h1>Route stops</h1><section v-for="(stop,i) in routeCustomers" :key="`${stop.route}-${stop.sequence_no}`" class="portal-card route-stop"><span class="delivery-index">{{stop.sequence_no||i+1}}</span><div><strong>{{stop.name}}</strong><small>{{stop.route}}</small></div><span class="portal-badge" v-if="stop.status_id">{{stop.status_id===3?'Delivered':stop.status_id===4?'Skipped':'Pending'}}</span><Link v-if="stop.delivery_id" :href="`/deliveries/${stop.delivery_id}`">Open</Link></section><p v-if="!routeCustomers.length" class="portal-card portal-muted">No route sequence is assigned.</p></template>
<template v-else-if="tab==='collections'"><p class="portal-eyebrow">RECORDED PAYMENTS TODAY</p><h1>Collections</h1><div class="portal-stats"><article><small>Total received</small><strong>₹{{Number(collections.total).toFixed(2)}}</strong></article><article><small>Cash</small><strong>₹{{Number(collections.cash).toFixed(2)}}</strong></article><article><small>UPI</small><strong>₹{{Number(collections.upi).toFixed(2)}}</strong></article></div><section class="portal-card"><div v-for="p in collections.records" :key="p.number" class="portal-row"><span><b>{{p.method}}</b><small>{{p.time}}</small></span><strong>₹{{p.amount}}</strong></div><p v-if="!collections.records.length" class="portal-muted">No collections recorded today.</p></section><Link href="/payments" class="portal-action">Payments</Link></template>
<template v-else><p class="portal-eyebrow">YOUR ACCOUNT</p><h1>Profile</h1><section class="portal-card"><div class="portal-profile"><span class="portal-avatar">{{$page.props.auth.user.name?.slice(0,1)}}</span><div><h2>{{$page.props.auth.user.name}}</h2><small>Delivery team</small></div></div><Link href="/change-password" class="portal-action">Change password</Link></section></template></div><nav class="portal-bottom"><Link v-for="[key,label,icon] in tabs" :key="key" :href="`/delivery?tab=${key}`" :class="{active:tab===key}"><i :class="`bi ${icon}`"></i><span>{{label}}</span></Link></nav></main></template>
